skill.procedure:
def apply(inputs, premises):
    question = inputs["current_question"]
    is_retention_query = "may retain some Confidential Information" in question and "return or destruction" in question
    retention_permission = False
    no_retention_requirement = False
    if "post_return_retention_expressly_permitted" in premises:
        retention_permission = premises["post_return_retention_expressly_permitted"]
    if "no_retention_after_return_or_destruction_required" in premises:
        no_retention_requirement = premises["no_retention_after_return_or_destruction_required"]
    if not is_retention_query:
        answer = "NotMentioned"
    elif retention_permission:
        answer = "Entailment"
    elif no_retention_requirement:
        answer = "Contradiction"
    else:
        answer = "NotMentioned"
    return {"answer": answer}
